def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n < 5:
        return 'C'

    opp_coop = 0
    for m, o in history:
        if o == 'C':
            opp_coop += 1

    if opp_coop == 0:
        return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'C':
        return 'C'

    window = history[-5:]
    recent_opp_def = 0
    for m, o in window:
        if o == 'D':
            recent_opp_def += 1

    if recent_opp_def >= 2:
        return 'D'

    return 'C'
